import type { Lesson } from '../types'
import { questions } from '../domain1/shared'

const id = 'd5-l05'
export const lesson: Lesson = {
  id, number: 56, domainId: 5, chapterId: '5.2', title: 'Config và Systems Manager: khắc phục có kiểm soát',
  summary: 'Thiết kế quy trình khắc phục khi phát hiện cấu hình không mong muốn: kiểm tra điều kiện trước khi sửa, dùng quyền tối thiểu, giới hạn phạm vi máy bị ảnh hưởng và xác minh kết quả sau thay đổi.', duration: 110,
  objectives: ["Phân biệt việc đánh giá mức tuân thủ với hành động sửa cấu hình không tuân thủ.", "Chọn Automation, Run Command hoặc State Manager theo yêu cầu thực hiện và duy trì cấu hình.", "Giới hạn phạm vi tác động; xử lý kết quả đánh giá cũ, vòng lặp và trường hợp chỉ một phần tài nguyên được sửa."],
  prerequisites: ["Biết quy tắc AWS Config, máy EC2 được Systems Manager quản lý và role dịch vụ trong IAM.", "Hiểu EventBridge và idempotency (khả năng chạy lặp an toàn) đã học ở bài 52."],
  sections: [
    { id: `${id}-compliance`, title: '1. Kết quả tuân thủ phản ánh đánh giá, không ngăn tài nguyên thay đổi', paragraphs: [
      'AWS Config ghi nhận cấu hình tài nguyên và đánh giá theo quy tắc để xác định compliant (tuân thủ) hoặc noncompliant (không tuân thủ). Đây là khả năng phát hiện; kết quả đánh giá không có nghĩa thao tác sai đã bị ngăn hay tài nguyên đã được sửa. Ví dụ, quy tắc có thể phát hiện S3 bucket chưa bật versioning, còn remediation (khắc phục) mới là bước gọi API để bật theo chính sách. Nếu yêu cầu là ngăn ngay một thao tác, cần cơ chế phòng ngừa phù hợp thay vì chỉ thêm Config. Nếu yêu cầu sửa sau khi phát hiện và có lịch sử thực hiện rõ ràng, Config kết hợp Systems Manager Automation là một hướng phù hợp.',
      'Mỗi đánh giá có thời điểm riêng và có thể chậm hơn cấu hình hiện tại. Cơ chế khắc phục tự động của Config dựa trên ảnh chụp kết quả tuân thủ, nên tài nguyên vừa được người vận hành sửa vẫn có thể bị chọn để xử lý lần nữa. Quy trình phải đọc trạng thái hiện tại, kiểm tra điều kiện và kết thúc an toàn nếu tài nguyên đã đúng. Không dùng kết quả không tuân thủ cũ như lệnh sửa vô điều kiện. Hãy giữ tài khoản, Region, mã tài nguyên và mã quy tắc trong lịch sử để xác nhận đúng đích. Trong bài thi, việc sự kiện xảy ra, Config ghi nhận và hành động bắt đầu ở các thời điểm khác nhau là yếu tố cần kiểm tra khi đánh giá tính an toàn của thiết kế.'
    ] },
    { id: `${id}-automation`, title: '2. Automation là quy trình thao tác nhiều bước có trạng thái', paragraphs: [
      'Systems Manager Automation thực hiện runbook (quy trình thao tác) gồm nhiều bước có thể quan sát riêng. Các bước có thể gọi API, chờ điều kiện, rẽ nhánh, chạy tập lệnh hoặc gọi Run Command khi cần thao tác hệ điều hành. Ví dụ, quy trình có thể tạo ảnh chụp trạng thái trước khi sửa hạ tầng. aws:executeAwsApi gọi API; aws:assertAwsResourceProperty kiểm tra thuộc tính; aws:waitForAwsResourceProperty chờ điều kiện; aws:branch chọn bước tiếp theo; aws:approve yêu cầu phê duyệt trong luồng được hỗ trợ. Tách các bước theo mục đích giúp nhận biết thao tác nào đã xong và lỗi ở đâu, thay vì giấu toàn bộ tiến trình trong một tập lệnh dài khó chạy lại.',
      'Role thực thi cần được cấp quyền gọi API trên đúng phạm vi tài nguyên và có chính sách tin cậy cho Systems Manager. Danh tính khởi chạy cũng phải có quyền bắt đầu quy trình và truyền role theo thiết kế. Vì thế, EventBridge khởi chạy được Automation chưa chứng minh các bước trong quy trình có quyền sửa tài nguyên. Hãy quản lý phiên bản tài liệu và giới hạn tham số vào những tài nguyên, giá trị hợp lệ, để thay đổi runbook không âm thầm mở rộng hành vi. Một quy trình dễ theo dõi thường lần lượt đọc điều kiện, sao lưu nếu cần, thực hiện thay đổi, kiểm tra lại rồi ghi kết quả. Nếu một bước thất bại, đầu ra phải cho biết các bước trước đã làm gì để người vận hành quyết định thử lại hay thực hiện thao tác bù trừ. Hủy lần chạy chỉ dừng quy trình theo cơ chế tương ứng, không tự đảo ngược những API đã hoàn thành.'
    ] },
    { id: `${id}-fleet`, title: '3. Run Command, State Manager và nút được quản lý', paragraphs: [
      "Run Command gửi command document (tài liệu lệnh) đến managed node (nút được Systems Manager quản lý) để làm việc trong hệ điều hành, chẳng hạn kiểm tra dịch vụ hoặc sửa tập tin cấu hình. Nút cần SSM Agent đang hoạt động, cơ chế xác thực và quyền phù hợp, cùng kết nối đến các điểm cuối dịch vụ. Với EC2, instance profile là một cách cấp quyền; Default Host Management Configuration là lựa chọn khác khi đáp ứng điều kiện của cơ chế này. Run Command không yêu cầu mở SSH chiều vào. Chọn đích bằng nhãn giúp quản lý nhiều máy, nhưng nhãn sai có thể chọn rộng hơn dự kiến, nên bắt đầu bằng một nhóm nhỏ đã xác nhận. Kết quả lệnh thành công chỉ phản ánh điều tài liệu lệnh kiểm tra, chưa chứng minh ứng dụng sẵn sàng phục vụ sau khởi động lại. Với một nhóm máy chỉ hoàn thành một phần, cần đọc đầu ra theo từng nút và kiểm tra thêm khả năng phục vụ.",
      'State Manager association (cấu hình liên kết của State Manager) mô tả desired state (trạng thái mong muốn), đối tượng áp dụng và lịch duy trì cấu hình. Cơ chế này phù hợp khi một tác nhân cần được duy trì ở trạng thái đã cài đặt hoặc một dịch vụ cần tiếp tục hoạt động theo chính sách. Run Command phù hợp hơn với thao tác cụ thể theo yêu cầu. Maintenance Windows xác định thời điểm được phép thực hiện công việc nhạy cảm; riêng lịch chạy không thay thế cơ chế duy trì trạng thái. Cũng cần phân biệt lịch định kỳ với lần chạy ban đầu: association mặc định có thể chạy ngay khi được tạo. Nếu chỉ được chạy từ thời điểm cron tiếp theo, hãy kiểm tra tùy chọn tương ứng trước khi tạo. Với nhóm nhiều máy, cần xác nhận nội dung tài liệu, hệ điều hành và danh sách đích để tránh áp dụng đúng lệnh cho sai nhóm máy.'
    ] },
    { id: `${id}-limits`, title: '4. Giới hạn tốc độ thực hiện và thay đổi hạ tầng theo sự kiện', paragraphs: [
      'MaxConcurrency giới hạn số đích chạy đồng thời; MaxErrors đặt ngưỡng lỗi để công cụ ngừng giao thêm công việc theo cơ chế của nó. Hai thiết lập này hạn chế phạm vi tác động nhưng không biến thao tác trên nhiều máy thành một giao dịch có thể hoàn tác. Khi ngưỡng lỗi được chạm tới, những đích đã nhận việc vẫn có thể tiếp tục chạy và phát sinh thêm lỗi, nên tổng lỗi cuối cùng có thể cao hơn ngưỡng. Hãy bắt đầu bằng canary (chạy thử trên một nhóm nhỏ), quan sát kết quả rồi mới mở rộng, đặc biệt khi tập lệnh phụ thuộc hệ điều hành hoặc phiên bản gói. Mức đồng thời cũng phải phù hợp với công suất phục vụ và phân bố máy giữa các vùng sẵn sàng. Một tỷ lệ nhỏ vẫn có thể gây gián đoạn nếu các máy bị tác động đang cùng phục vụ một phần việc quan trọng.',
      "Tự động hóa theo sự kiện có thể đổi số máy mong muốn (desired capacity), launch template hoặc cấu hình tài nguyên, nhưng cần xác định cơ chế nào có quyền quyết định trạng thái cuối cùng. Nếu Lambda liên tục đặt số máy mong muốn cố định trong khi target tracking điều chỉnh theo tải, hai cơ chế có thể sửa qua sửa lại. Hãy chọn chính sách mở rộng phù hợp, phối hợp giới hạn tối thiểu và tối đa cùng thời gian ổn định. Sửa launch template cũng không tự cập nhật những máy đang chạy; cần kế hoạch thay thế hoặc làm mới nếu muốn chúng nhận cấu hình mới. Những thay đổi trực tiếp ở môi trường chạy nên được phản ánh vào IaC hoặc cấu hình nguồn được quản lý để lần triển khai sau không ghi đè lại bản sửa."
    ] },
    { id: `${id}-safety`, title: '5. Tái đánh giá, ngoại lệ và bằng chứng phục hồi', paragraphs: [
      'Quy trình khắc phục cần điều kiện trước, thao tác có thể chạy lặp an toàn và điều kiện cần đạt sau xử lý. Ví dụ, chỉ bật versioning khi bucket chưa bật hoặc đang Suspended, đồng thời xác nhận tham số ánh xạ đúng bucket. Với thay đổi có thể gây gián đoạn như đóng quyền security group hoặc khởi động lại cơ sở dữ liệu, áp dụng đánh giá tác động, phê duyệt hoặc canary phù hợp. Thử lại có giới hạn giúp chịu lỗi tạm thời; thử vô hạn với AccessDenied chỉ thêm chi phí và thông tin nhiễu. Ngoại lệ hợp lệ cũng cần phạm vi, người phụ trách và thời hạn để công cụ với người vận hành không liên tục sửa ngược nhau.',
      'Sau hành động, đọc lại qua API rồi chờ Config đánh giá lại theo cơ chế phù hợp. API trả Success chưa chứng minh người dùng đã hết lỗi; ngược lại, Config chưa hiển thị tuân thủ ngay cũng chưa đủ kết luận thay đổi thất bại. Lưu mã thực thi Automation, đầu ra từng bước, mã lệnh và kết quả từng nút cùng sự kiện, quy tắc liên quan. Nếu chỉ một phần đích được sửa, giữ thông tin đó để quyết định thử lại hay bù trừ; đừng chạy lại mọi thứ với quyền rộng hơn khi chưa hiểu trạng thái. Sau sự cố, cập nhật phạm vi sự kiện, quyền, điều kiện hoặc cấu hình nguồn gây lỗi để giảm khả năng lặp lại.'
    ] },
  ],
  diagram: { title: 'Chu trình khắc phục có điều kiện', steps: [
    { label: 'Phát hiện', detail: 'Kết quả đánh giá Config hoặc sự kiện cho thấy cấu hình bị sai lệch.' },
    { label: 'Đọc trạng thái hiện tại', detail: 'Xác nhận đúng tài khoản, tài nguyên và điều kiện hiện tại trước khi thực hiện.' },
    { label: 'Cấp quyền và giới hạn phạm vi', detail: 'Cấp quyền tối thiểu, chạy thử trên nhóm nhỏ và áp dụng phê duyệt, giới hạn tốc độ khi cần.' },
    { label: 'Thực hiện và xác minh', detail: 'Thực hiện thao tác có thể chạy lặp an toàn, rồi kiểm tra trạng thái cần đạt.' },
    { label: 'Đánh giá lại và lưu kết quả', detail: 'Cập nhật kết quả tuân thủ và lưu thông tin để kiểm toán từng lần thực thi.' },
  ], caption: "Quy trình lần lượt phát hiện sai lệch, đọc trạng thái hiện tại, thực thi trong phạm vi đã giới hạn, xác minh rồi đánh giá lại. Kết quả đánh giá mức tuân thủ có thể đã cũ, vì vậy quy trình không được bỏ qua bước đọc trạng thái hiện tại." },
  scenarios: [
    { title: 'Bucket đã sửa nhưng vẫn bị chọn', context: 'Kỹ sư bật versioning thủ công sau kết quả đánh giá không tuân thủ, sau đó khắc phục tự động vẫn khởi chạy.', solution: 'Runbook gọi GetBucketVersioning để đọc trạng thái mới nhất. Nếu đã là Enabled, quy trình không thay đổi gì, ghi kết quả rồi chờ Config đánh giá lại; không đưa bucket về trạng thái cũ chỉ để thực hiện lại thao tác sửa.', tradeoff: 'Quy trình cần thêm một bước đọc trạng thái, nhưng nhờ đó tránh thực hiện thay đổi không cần thiết khi kết quả đánh giá đã cũ.' },
    { title: 'Khởi động lại tác nhân trên nhiều hệ điều hành', context: 'Tập lệnh khởi động lại dịch vụ dùng lệnh Linux nhưng nhãn đích gồm cả Windows; triển khai trên diện rộng khiến nhiều lần gọi thất bại.', solution: 'Chọn tài liệu lệnh phù hợp với từng nền tảng, thử trên nhóm nhỏ, giới hạn số đích chạy đồng thời và ngưỡng lỗi; kiểm tra kết quả từng nút trước khi mở rộng.', tradeoff: 'Nhóm phải quản lý tài liệu và nhánh xử lý cho từng hệ điều hành. Đổi lại, kết quả từng nút giúp giới hạn ảnh hưởng và xác định chính xác các máy còn lỗi.' },
  ],
  keyTakeaways: ['Config phát hiện cấu hình không tuân thủ; việc sửa tài nguyên cần hành động và quyền thực thi riêng.', 'Kết quả đánh giá có thể đã cũ, nên quy trình phải đọc trạng thái hiện tại và có thể chạy lặp mà không gây tác động thừa.', "Run Command thực hiện lệnh trên các nút được quản lý; Automation điều phối nhiều bước; State Manager duy trì trạng thái mong muốn.", 'MaxErrors hạn chế việc giao thêm công việc, không tự hoàn tác các thao tác đã chạy.'],
  examTraps: ['Không cho rằng tài nguyên đang tuân thủ sẽ không bao giờ bị chọn để khắc phục tự động.', 'Không coi API trả Success là bằng chứng ứng dụng đã phục vụ bình thường hoặc Config đã cập nhật kết quả ngay.', 'Không cho rằng cấp quyền cho nguồn kích hoạt theo sự kiện sẽ tự cấp đủ quyền sửa tài nguyên cho role thực thi.', 'Không để quy trình tự động trong môi trường chạy sửa ngược với IaC hoặc bộ điều khiển mở rộng tài nguyên mà không có cơ chế quyết định trạng thái cuối cùng rõ ràng.'],
  code: { title: 'Khắc phục cấu hình versioning bằng Config và runbook được quản lý', deployable: false,
    cloudformation: `Resources:
  VersioningRule:
    Type: AWS::Config::ConfigRule
    Properties:
      Scope: {ComplianceResourceTypes: ['AWS::S3::Bucket']}
      Source:
        Owner: AWS
        SourceIdentifier: S3_BUCKET_VERSIONING_ENABLED
  Remediation:
    Type: AWS::Config::RemediationConfiguration
    Properties:
      ConfigRuleName: !Ref VersioningRule
      TargetType: SSM_DOCUMENT
      TargetId: AWS-ConfigureS3BucketVersioning
      Automatic: false
      Parameters:
        BucketName:
          ResourceValue: {Value: RESOURCE_ID}
        VersioningState:
          StaticValue: {Values: [Enabled]}
        AutomationAssumeRole:
          StaticValue:
            Values: [!GetAtt RemediationRole.Arn]
# Requires Config recorder/delivery setup and scoped RemediationRole.
# Review current-state checks before enabling automatic remediation.`,
    terraform: `resource "aws_config_remediation_configuration" "versioning" {
  config_rule_name = aws_config_config_rule.versioning.name
  target_type      = "SSM_DOCUMENT"
  target_id        = "AWS-ConfigureS3BucketVersioning"
  automatic        = false
  parameter {
    name           = "BucketName"
    resource_value = "RESOURCE_ID"
  }
  parameter {
    name         = "VersioningState"
    static_value = "Enabled"
  }
  parameter {
    name         = "AutomationAssumeRole"
    static_value = aws_iam_role.remediation.arn
  }
}`,
    explanation: 'Đoạn mã dùng chế độ khắc phục thủ công để người vận hành rà soát phạm vi trước. Cần bổ sung bộ ghi Config, nơi nhận dữ liệu và role có chính sách tin cậy, quyền phù hợp. Runbook AWS-ConfigureS3BucketVersioning dùng các tham số BucketName và VersioningState. Trước khi bật khắc phục tự động trong môi trường chính thức, phải xem xét kết quả đánh giá có thể đã cũ, phạm vi tài nguyên và các điều kiện bảo vệ; không áp dụng tự động trên toàn tài khoản chỉ từ đoạn mẫu.'
  },
  lab: { title: 'Khắc phục thủ công versioning trên một bucket trống', duration: 75,
    prerequisites: ['Có môi trường thử nghiệm đã bật ghi nhận cấu hình S3 trong Config và hiểu chi phí ghi nhận, đánh giá.', 'Có một bucket thực hành trống, không công khai, không dùng chung và không chứa dữ liệu khách hàng.', 'Role Automation chỉ được gọi GetBucketVersioning và PutBucketVersioning trên bucket thử nghiệm; danh tính khởi chạy có các quyền cần thiết để bắt đầu và truyền role.'],
    cost: 'AWS Config ghi nhận/đánh giá, Systems Manager Automation, S3 và nhật ký có thể tính phí. Chỉ dùng một bucket trống; không bật ghi nhận cấu hình toàn bộ tổ chức cho bài thử.',
    steps: [
      { title: 'Xác nhận bucket và trạng thái', detail: 'Ghi lại tài khoản, Region và tên bucket được tạo riêng; dùng API đọc trạng thái versioning của bucket thử nghiệm.', command: 'aws s3api get-bucket-versioning --bucket study-remediation-unique-name', expected: "Đã xác nhận bucket thực hành chưa ở trạng thái Enabled và không chứa đối tượng cần giữ. Tên trong lệnh khớp với bucket được phép sửa." },
      { title: 'Thêm quy tắc Config có phạm vi', detail: 'Tạo quy tắc kiểm tra versioning của S3 trong môi trường thử nghiệm, giới hạn phạm vi tài nguyên phù hợp với thực hành. Xem thời điểm đánh giá và mã tài nguyên.', expected: 'Config đánh giá tài nguyên thực hành là không tuân thủ; người học phân biệt được thời điểm phát hiện với trạng thái hiện tại.' },
      { title: 'Đọc runbook trước khi chạy', detail: 'Mở AWS-ConfigureS3BucketVersioning, kiểm tra tham số BucketName, VersioningState và AutomationAssumeRole; rà soát API/quyền và không chọn Suspended vô ý.', expected: "Đã xác định tham số bật versioning, các API runbook sẽ gọi và role chịu trách nhiệm thực hiện." },
      { title: 'Chạy khắc phục thủ công', detail: 'Ánh xạ RESOURCE_ID vào BucketName, chọn Enabled và role chỉ có quyền trên bucket thử nghiệm. Chạy khắc phục cho một tài nguyên rồi theo dõi từng bước Automation.', expected: 'Lần thực thi có ID và đầu ra từng bước; role không được phép đổi bucket ngoài phạm vi.' },
      { title: 'Đọc trạng thái sau và mức tuân thủ', detail: 'Gọi lại GetBucketVersioning rồi theo dõi lần đánh giá tiếp theo của Config. Đối chiếu trạng thái Enabled mà API trả về với thời điểm bảng giám sát chuyển sang tuân thủ.', expected: "API trả về Enabled. Kết quả đánh giá Config được đối chiếu theo thời điểm cập nhật riêng; người học không gửi thêm yêu cầu sửa chỉ vì giao diện chưa cập nhật." },
      { title: 'Thiết kế điều kiện bảo vệ trên giấy', detail: 'Mô tả một runbook tùy chỉnh: đọc trạng thái, kết thúc không thay đổi khi tài nguyên đã đúng và xác minh sau thao tác sửa. Ghi giới hạn số đích chạy đồng thời, ngưỡng lỗi và ngoại lệ khi áp dụng cho nhóm máy.', command: 'aws configservice describe-remediation-execution-status --config-rule-name study-versioning-rule', expected: 'Truy vết được từng lần thực thi và lỗi, đồng thời xác định được các điều kiện bảo vệ trước khi bật chế độ tự động.' },
    ], cleanup: ["Gỡ cấu hình khắc phục và quy tắc được tạo riêng cho bài thực hành để tránh tiếp tục tự sửa ngoài ý muốn.", "Xác nhận đúng bucket thực hành trước khi xóa. Nếu đã có đối tượng hoặc phiên bản thử nghiệm, kiểm tra và xóa chúng qua bảng điều khiển trước khi xóa bucket.", "Xóa role và nhật ký được tạo riêng cho bài thực hành. Chỉ tắt hoặc thu hẹp bộ ghi cấu hình Config nếu bộ ghi đó cũng được tạo riêng; không tắt bộ ghi dùng chung."],
    challenge: 'Thiết kế triển khai thử trên nhóm nhỏ rồi mở rộng từng đợt cho 100 nút được quản lý: chọn đích, số đích chạy đồng thời và ngưỡng lỗi, điều kiện dừng và xác minh khả năng phục vụ của ứng dụng; giải thích vì sao ngưỡng lỗi không bảo đảm hoàn tác toàn bộ thao tác.'
  },
  sources: [
    { title: 'Domain 5 configuration response', url: 'https://docs.aws.amazon.com/aws-certification/latest/devops-engineer-professional-02/devops-engineer-professional-02-domain5.html' },
    { title: 'Config auto remediation and stale snapshots', url: 'https://docs.aws.amazon.com/config/latest/developerguide/setup-autoremediation.html' },
    { title: 'State Manager associations', url: 'https://docs.aws.amazon.com/systems-manager/latest/userguide/systems-manager-state.html' },
    { title: 'Automation action reference', url: 'https://docs.aws.amazon.com/systems-manager/latest/userguide/automation-actions.html' },
    { title: 'AWS-ConfigureS3BucketVersioning parameters', url: 'https://docs.aws.amazon.com/systems-manager-automation-runbooks/latest/userguide/automation-aws-configures3bucketversioning.html' },
    { title: 'Automation concurrency and errors', url: 'https://docs.aws.amazon.com/systems-manager/latest/APIReference/API_StartAutomationExecution.html' },
  ], reviewedAt: '2026-10-19',
  questions: questions(id, '5.2', [
    { section: 'compliance', en: 'A Config rule marks a bucket noncompliant. The team expected the rule itself to enable versioning automatically. What is missing?', vi: "Một quy tắc Config đánh dấu bucket không tuân thủ. Nhóm kỳ vọng chính quy tắc này sẽ tự bật versioning. Thiết kế còn thiếu gì?", options: [
      ['A larger configuration item history without any action mapping', "Lưu thêm lịch sử cấu hình nhưng không gắn với thao tác khắc phục", "Lịch sử cấu hình giúp xem lại trạng thái và các thay đổi trước đó. Tuy nhiên, lưu thêm lịch sử không tạo ra bước gọi API để bật versioning."], ['A different dashboard refresh interval only', "Chỉ thay đổi chu kỳ làm mới bảng giám sát", "Làm mới bảng giám sát chỉ cập nhật thông tin được hiển thị. Thao tác này không sửa cấu hình bucket, nên chưa đáp ứng yêu cầu tự bật versioning."], ['An authorized remediation action associated with detection', "Gắn kết quả phát hiện với một thao tác khắc phục đã được cấp quyền", "Quy tắc Config xác định cấu hình không tuân thủ, còn hành động khắc phục mới thực hiện thay đổi. Hành động đó phải có quyền gọi API trên đúng bucket."], ['Only a longer retention period on Config delivery S3', "Chỉ tăng thời hạn lưu dữ liệu Config trong S3", "Thời hạn lưu quyết định dữ liệu Config được giữ bao lâu. Nó không cấp quyền hoặc gọi API bật versioning cho bucket cần khắc phục."],
    ], correct: ['C'], explanation: "Config tách việc đánh giá khỏi việc khắc phục. Muốn tự bật versioning, nhóm phải gắn kết quả phát hiện với một hành động có quyền sửa đúng bucket; lưu thêm dữ liệu hoặc làm mới giao diện không thay thế bước này.", tags: ['Config', 'detection-vs-remediation'] },
    { section: 'compliance', en: 'A resource was fixed manually, yet Config auto remediation starts from an older noncompliant snapshot. What should the runbook do first?', vi: "Tài nguyên đã được sửa thủ công, nhưng Config vẫn kích hoạt khắc phục tự động dựa trên kết quả đánh giá không tuân thủ trước đó. Quy trình cần làm gì đầu tiên?", options: [
      ['Read current state and safely no-op if the desired condition already holds', "Đọc trạng thái hiện tại và kết thúc an toàn mà không thay đổi gì nếu tài nguyên đã đúng", "Kết quả đánh giá có thể cũ hơn cấu hình thực tế. Đọc lại trạng thái giúp quy trình nhận ra tài nguyên đã đúng và tránh thực hiện thay đổi không còn cần thiết."], ['Reapply every destructive step unconditionally', "Áp dụng lại mọi bước có tính phá hủy mà không kiểm tra điều kiện", "Chạy lại vô điều kiện có thể tiếp tục thay đổi hoặc phá hủy một tài nguyên đã được sửa. Quy trình vẫn đang hành động theo dữ liệu cũ thay vì nhu cầu hiện tại."], ['Turn the resource back to the old noncompliant state', "Đưa tài nguyên về trạng thái không tuân thủ trước đó", "Mục tiêu là giữ cấu hình đúng, không tái tạo lỗi để thực hiện lại thao tác sửa. Đưa tài nguyên về trạng thái cũ tạo thêm sai lệch và rủi ro không cần thiết."], ['Disable all Config rules across the organization', "Tắt mọi quy tắc Config trong toàn tổ chức", "Tắt toàn bộ quy tắc làm mất khả năng phát hiện ở nhiều tài nguyên khác. Phạm vi này lớn hơn vấn đề cần xử lý và không bổ sung điều kiện bảo vệ cho runbook."],
    ], correct: ['A'], explanation: "Kết quả đánh giá mô tả trạng thái tại một thời điểm, còn quyết định sửa phải dựa trên trạng thái hiện tại. Kiểm tra trước khi thay đổi giúp quy trình kết thúc an toàn khi người vận hành đã sửa xong tài nguyên.", tags: ['stale-snapshot', 'idempotency'] },
    { section: 'compliance', en: 'Which TWO identifiers should be retained to prevent ambiguous remediation targets? Choose two.', vi: "Cần giữ hai nhóm thông tin định danh nào để tránh xác định nhầm tài nguyên cần khắc phục? Chọn hai đáp án.", options: [
      ['Only a friendly resource nickname reused across accounts', "Chỉ tên gọi dễ nhớ được dùng lại cho tài nguyên ở nhiều tài khoản", "Tên gọi dễ nhớ hỗ trợ người vận hành, nhưng có thể trùng giữa các tài khoản. Chỉ giữ tên đó chưa đủ để xác định duy nhất tài nguyên cần sửa."], ['The account and Region containing the target', "Tài khoản và Region chứa tài nguyên cần khắc phục", "Tài khoản và Region xác định phạm vi chứa tài nguyên. Hai thông tin này giúp phân biệt những tài nguyên có tên hoặc mã tương tự ở các môi trường khác nhau."], ['Only the time an operator opened the console', "Chỉ thời điểm người vận hành mở bảng điều khiển", "Thời điểm mở bảng điều khiển cho biết một hoạt động của người dùng, không cho biết tài nguyên nào bị đánh giá hoặc thao tác sửa nào cần thực hiện."], ['The resource ID and associated rule or triggering evaluation', "Mã tài nguyên cùng quy tắc hoặc lần đánh giá đã kích hoạt khắc phục", "Mã tài nguyên xác định đối tượng, còn quy tắc hoặc lần đánh giá cho biết vì sao quy trình được khởi chạy. Giữ cả hai giúp truy vết đúng thao tác và nguyên nhân."], ['Only a count of resources in the account', "Chỉ tổng số tài nguyên trong tài khoản", "Tổng số tài nguyên là thông tin thống kê, không phân biệt được đối tượng cụ thể. Quy trình không thể dùng số lượng này để chọn đúng tài nguyên cần sửa."],
    ], correct: ['B', 'D'], explanation: "Cần xác định cả nơi chứa tài nguyên và lý do khởi chạy hành động: tài khoản, Region, mã tài nguyên cùng quy tắc hoặc lần đánh giá liên quan. Tên gọi hoặc số lượng tài nguyên không cung cấp đủ thông tin để chọn đúng đối tượng.", tags: ['target-scope', 'audit'] },
    { section: 'automation', en: 'A remediation must inspect state, create a snapshot, modify configuration, and verify recovery. Which approach is most maintainable?', vi: "Quy trình khắc phục phải kiểm tra trạng thái, tạo snapshot (ảnh chụp trạng thái), sửa cấu hình rồi xác minh khả năng phục hồi. Cách tổ chức nào dễ bảo trì nhất?", options: [
      ['A notification-only SNS topic with no execution state', "Chỉ dùng chủ đề SNS để thông báo, không theo dõi trạng thái thực thi", "SNS chuyển thông báo đến bên nhận nhưng không tự tổ chức các bước kiểm tra, sao lưu, sửa và xác minh. Phương án này chưa có cơ chế điều phối quy trình cần thiết."], ['A recurring shell script with no step-level outcomes', "Dùng tập lệnh shell chạy định kỳ nhưng không ghi kết quả riêng cho từng bước", "Tập lệnh có thể thực hiện thao tác, nhưng thiếu kết quả từng bước khiến nhóm khó biết việc nào đã xong khi lỗi giữa chừng. Vì vậy, việc quyết định thử lại hoặc bù trừ sẽ khó bảo trì hơn."], ['A Config dashboard without an action integration', "Dùng bảng giám sát Config không tích hợp hành động khắc phục", "Bảng giám sát giúp quan sát kết quả đánh giá nhưng không thực hiện chuỗi thao tác sửa. Hiển thị cấu hình không thay thế một quy trình có trạng thái và xử lý lỗi."], ['An Automation runbook with explicit precondition, action, and verification steps', "Dùng runbook Automation với các bước kiểm tra điều kiện, thực hiện thay đổi và xác minh rõ ràng", "Automation lưu trạng thái và đầu ra của từng bước. Tách rõ các thao tác giúp xác định phần đã hoàn thành, nơi phát sinh lỗi và bước xử lý tiếp theo."],
    ], correct: ['D'], explanation: "Runbook với các bước rõ ràng giúp nhóm theo dõi lần lượt việc kiểm tra, sao lưu, sửa và xác minh. Nếu quy trình dừng giữa chừng, kết quả từng bước là cơ sở để thử lại hoặc bù trừ thay vì chạy lại toàn bộ mà chưa biết tác động trước đó.", tags: ['Automation', 'runbook'] },
    { section: 'automation', en: 'EventBridge can start an Automation execution, but its API modification step gets AccessDenied. What should be checked first?', vi: "EventBridge đã khởi chạy Automation, nhưng bước gọi API sửa cấu hình báo AccessDenied. Nên kiểm tra gì trước?", options: [
      ['The Automation execution role permissions for the denied API and resource', "Quyền của role thực thi Automation đối với API và tài nguyên bị từ chối", "Quyền bắt đầu Automation và quyền gọi API trong một bước là hai phạm vi khác nhau. Khi lần chạy đã bắt đầu, cần kiểm tra role đang gọi API có quyền thực hiện thao tác trên tài nguyên đó hay không."], ['Only the EventBridge pattern, since an execution already started', "Chỉ kiểm tra mẫu lọc EventBridge dù lần thực thi đã bắt đầu", "Mẫu lọc đã cho phép sự kiện khởi chạy Automation. Lỗi AccessDenied xuất hiện ở bước sửa cấu hình nên cần kiểm tra quyền của chủ thể gọi API, không chỉ mẫu lọc sự kiện."], ['Only the notification email subscription', "Chỉ kiểm tra đăng ký nhận email thông báo", "Đăng ký email quyết định nơi nhận thông báo, không cấp quyền sửa tài nguyên. Thay đổi đăng ký không giải quyết được lỗi AccessDenied ở bước gọi API."], ['Only Config report retention', "Chỉ kiểm tra thời hạn lưu báo cáo Config", "Thời hạn lưu báo cáo quyết định thời gian giữ dữ liệu. Nó không quyết định role thực thi có được gọi API sửa cấu hình hay không."],
    ], correct: ['A'], explanation: "Danh tính khởi chạy và role thực thi chịu trách nhiệm ở các bước khác nhau. EventBridge đã khởi chạy được Automation, vì vậy bước tiếp theo là kiểm tra quyền của chủ thể gọi API bị từ chối trên đúng tài nguyên.", tags: ['execution-role', 'AccessDenied'] },
    { section: 'automation', en: 'Which TWO runbook steps directly support safe conditional remediation? Choose two.', vi: "Hai bước nào trong runbook trực tiếp giúp khắc phục an toàn theo điều kiện? Chọn hai đáp án.", options: [
      ['A final command that always suppresses errors', "Dùng lệnh cuối luôn che giấu lỗi", "Che giấu lỗi khiến người vận hành mất tín hiệu để xác định thao tác có thành công hay không. Cách này không kiểm tra điều kiện trước hoặc trạng thái cần đạt sau thay đổi."], ['A read or assertion of current resource state before changing it', "Đọc hoặc kiểm chứng trạng thái hiện tại của tài nguyên trước khi thay đổi", "Bước này xác nhận tài nguyên có còn cần sửa và có đúng đối tượng được phép sửa hay không. Nhờ đó, quy trình không hành động vô điều kiện theo kết quả đánh giá cũ."], ['Only a generic success notification before action', "Chỉ gửi một thông báo thành công chung trước khi thực hiện thao tác", "Thông báo được gửi trước hành động chưa thể phản ánh kết quả sửa. Nó không xác nhận điều kiện đầu vào và cũng không chứng minh tài nguyên đã đạt trạng thái mong muốn."], ['Retrying forever regardless of error class', "Thử lại vô hạn mà không phân biệt loại lỗi", "Lặp lại cùng yêu cầu không tự khắc phục được quyền còn thiếu hoặc tham số sai. Thử lại vô hạn còn làm tăng số lần tác động khi quy trình chưa hiểu nguyên nhân lỗi."], ['A read-after-change postcondition check', "Đọc lại trạng thái sau thay đổi để kiểm tra điều kiện cần đạt", "Kết quả đọc sau thay đổi cho biết tài nguyên đã đạt trạng thái yêu cầu hay chưa. Đây là bằng chứng xác minh, thay vì chỉ dựa vào việc bước gọi API đã kết thúc."],
    ], correct: ['B', 'E'], explanation: "Kiểm tra trước thay đổi xác nhận thao tác còn cần thiết và đúng tài nguyên; kiểm tra sau thay đổi xác nhận kết quả thực tế. Hai bước bổ sung cho nhau, giúp tránh cả việc sửa thừa lẫn báo thành công quá sớm.", tags: ['precondition', 'postcondition'] },
    { section: 'automation', en: 'A high-impact single-account remediation requires a designated owner to approve before a disruptive API step. Which action should be considered?', vi: "Quy trình khắc phục có tác động lớn trong một tài khoản cần người phụ trách phê duyệt trước bước gọi API có thể gây gián đoạn. Nên cân nhắc hành động nào?", options: [
      ['aws:sleep with a fixed delay as an assumed approval', "Dùng aws:sleep với thời gian chờ cố định và coi hết thời gian chờ là đã được duyệt", "aws:sleep chỉ trì hoãn bước tiếp theo. Thời gian đã trôi qua không chứng minh người có thẩm quyền đã xem xét và đồng ý thực hiện thay đổi."], ['Only an SNS publish followed immediately by modification', "Chỉ gửi thông báo SNS rồi sửa ngay", "Thông báo cho người phụ trách biết có thay đổi, nhưng quy trình vẫn tiếp tục ngay. Vì không chờ quyết định, cách này chưa đáp ứng yêu cầu phê duyệt trước thao tác."], ['aws:approve in a supported workflow with defined approvers and timeout', "Dùng aws:approve trong quy trình được hỗ trợ, với người phê duyệt và thời gian chờ được xác định rõ", "aws:approve tạo bước chờ quyết định phê duyệt trong quy trình được hỗ trợ. Xác định người duyệt và thời gian chờ giúp kiểm soát việc đi tiếp trước bước có thể gây gián đoạn."], ['A broader administrator policy on the target role', "Gắn chính sách quản trị rộng hơn cho role đích", "Mở rộng quyền có thể cho phép thêm thao tác, nhưng không tạo ra bước chờ người phụ trách quyết định. Quyền thực thi và sự phê duyệt là hai yêu cầu khác nhau."],
    ], correct: ['C'], explanation: "Phê duyệt cần một bước có trạng thái để chờ quyết định của đúng người, không chỉ gửi tin nhắn hoặc trì hoãn. Trong quy trình được hỗ trợ, aws:approve đáp ứng yêu cầu đó trước thao tác có thể gây gián đoạn.", tags: ['approval', 'Automation'] },
    { section: 'fleet', en: 'An operator needs to restart a service once on selected managed nodes and collect per-node output. Which capability is the direct fit?', vi: "Người vận hành cần khởi động lại dịch vụ một lần trên các nút được quản lý đã chọn và thu đầu ra riêng của từng nút. Tính năng nào phù hợp trực tiếp nhất?", options: [
      ['Only Config inventory recording', "Chỉ ghi nhận thông tin tài nguyên trong Config", "Config ghi nhận và đánh giá cấu hình, không gửi lệnh khởi động lại dịch vụ trong hệ điều hành. Phương án này chưa thực hiện thao tác hoặc thu đầu ra từng nút như đề yêu cầu."], ['An EventBridge archive alone', "Chỉ dùng kho lưu trữ sự kiện EventBridge", "Kho lưu trữ giữ sự kiện để sử dụng lại khi cần, không tự chạy lệnh hệ điều hành. Chỉ lưu sự kiện chưa đáp ứng yêu cầu khởi động lại dịch vụ."], ['Only an Auto Scaling desired-capacity change', "Chỉ thay đổi desired capacity (số máy mong muốn) của Auto Scaling", "Thay đổi số máy mong muốn điều chỉnh quy mô nhóm. Nó không tương đương việc gửi lệnh khởi động lại một dịch vụ rồi thu kết quả trên từng máy đã chọn."], ['Systems Manager Run Command with scoped targets and a reviewed document', "Dùng Systems Manager Run Command với phạm vi đích giới hạn và tài liệu lệnh đã rà soát", "Run Command gửi lệnh hệ điều hành tới các nút được quản lý và cung cấp kết quả từng lần gọi. Phạm vi đích và tài liệu đã rà soát giúp kiểm soát máy nào sẽ thực hiện thao tác."],
    ], correct: ['D'], explanation: "Run Command phù hợp với thao tác hệ điều hành theo yêu cầu và cho phép xem đầu ra từng nút. Người vận hành vẫn phải rà soát danh sách đích cùng tài liệu lệnh vì chúng quyết định nơi chạy và nội dung thao tác.", tags: ['Run-Command', 'managed-node'] },
    { section: 'fleet', en: 'A security agent must remain installed and running across a growing fleet on a defined schedule. Which mechanism best expresses this desired state?', vi: "Phần mềm bảo mật phải luôn ở trạng thái đã cài đặt và đang hoạt động trên nhóm máy ngày càng mở rộng, theo một lịch xác định. Cơ chế nào thể hiện trạng thái mong muốn phù hợp nhất?", options: [
      ['A State Manager association targeting the intended fleet', "Dùng State Manager association cho đúng nhóm máy cần quản lý", "Association kết hợp cấu hình cần duy trì, đối tượng áp dụng và lịch thực hiện. Cơ chế này phù hợp với yêu cầu duy trì phần mềm trên cả nhóm máy tiếp tục mở rộng."], ['A one-time manual SSH session on the current instances only', "Chỉ đăng nhập SSH thủ công một lần vào các máy hiện có", "Một lần thao tác thủ công chỉ tác động đến các máy được truy cập lúc đó. Nó không tự duy trì cấu hình theo lịch hoặc áp dụng cho máy mới trong nhóm."], ['Only a report of agent failures with no action', "Chỉ báo cáo lỗi của phần mềm bảo mật mà không thực hiện hành động nào", "Báo cáo giúp phát hiện phần mềm gặp lỗi, nhưng không cài đặt hoặc đưa phần mềm trở lại trạng thái mong muốn. Đề yêu cầu cơ chế duy trì chứ không chỉ quan sát."], ['Only increasing the application ALB timeout', "Chỉ tăng thời gian chờ của ALB phục vụ ứng dụng", "Thời gian chờ của ALB liên quan đến xử lý kết nối ứng dụng. Thay đổi này không cài đặt hoặc khởi động phần mềm bảo mật trên các nút."],
    ], correct: ['A'], explanation: "State Manager association mô tả cấu hình mong muốn, nhóm máy áp dụng và lịch duy trì. Nhờ vậy, nó đáp ứng yêu cầu lâu dài rõ hơn một thao tác thủ công chỉ chạy một lần trên các máy hiện có.", tags: ['State-Manager', 'desired-state'] },
    { section: 'fleet', en: 'A new State Manager association must not execute until the next approved cron interval. What should be reviewed?', vi: "Một association mới của State Manager chỉ được phép chạy từ thời điểm cron tiếp theo đã được phê duyệt. Cần kiểm tra điều gì?", options: [
      ['Only whether the document title contains the word approved', "Chỉ kiểm tra tiêu đề tài liệu có chứa từ approved hay không", "Tiêu đề chỉ là tên mô tả, không điều khiển thời điểm thực thi. Đặt tên là approved không ngăn lần chạy ban đầu xảy ra khi tạo association."], ['The apply-only-at-cron-interval behavior rather than assuming creation is inert', "Kiểm tra hành vi apply-only-at-cron-interval thay vì mặc định rằng tạo association sẽ chưa chạy gì", "Association mặc định có thể chạy ngay khi được tạo. Cần xem thiết lập chỉ áp dụng từ kỳ cron để đáp ứng yêu cầu chưa chạy trước thời điểm được phép."], ['Only a longer output-retention policy', "Chỉ kéo dài thời hạn lưu đầu ra", "Thời hạn lưu quyết định dữ liệu kết quả được giữ bao lâu sau khi chạy. Nó không trì hoãn hoặc ngăn lần thực thi ban đầu của association."], ['The number of old command IDs in history', "Kiểm tra số mã lệnh cũ trong lịch sử", "Số mã lệnh đã có là thông tin lịch sử, không phải thiết lập điều khiển lịch của association mới. Nó không bảo đảm chờ đến kỳ cron tiếp theo."],
    ], correct: ['B'], explanation: "Lịch định kỳ và lần thực thi ban đầu là hai điều cần phân biệt. Vì association có thể chạy ngay khi tạo, nhóm phải rà soát hành vi apply-only-at-cron-interval trước khi áp dụng cho các máy.", tags: ['association-schedule', 'cron'] },
    { section: 'fleet', en: 'Which TWO prerequisites belong in managed-node Run Command troubleshooting? Choose two.', vi: "Cần kiểm tra hai điều kiện nào khi điều tra lỗi Run Command trên nút được quản lý? Chọn hai đáp án.", options: [
      ['An inbound SSH rule open to all internet addresses', "Mở cổng SSH chiều vào cho mọi địa chỉ Internet", "Run Command nhận lệnh qua SSM Agent, không cần SSH công khai. Mở cổng cho toàn Internet không khắc phục điều kiện nhận lệnh của Agent và còn mở rộng rủi ro truy cập."], ['A CodeDeploy AppSpec copied to every bucket', "Sao chép AppSpec của CodeDeploy vào mọi bucket", "AppSpec mô tả nội dung triển khai của CodeDeploy, không phải điều kiện để SSM Agent nhận lệnh Run Command. Sao chép tệp này không giải quyết vấn đề quản lý nút."], ['SSM Agent health and connectivity to required endpoints', "Kiểm tra SSM Agent có hoạt động và kết nối được đến các điểm cuối cần thiết hay không", "SSM Agent phải hoạt động và liên lạc được với dịch vụ để nhận lệnh, gửi trạng thái và kết quả. Lỗi ở một trong các điều kiện này có thể làm nút không xử lý được yêu cầu."], ['The node role permissions and correct target selection', "Kiểm tra quyền của role trên nút và xác nhận đã chọn đúng đích", "Role cung cấp quyền cho nút tương tác với dịch vụ; cách chọn đích quyết định nút nào nhận yêu cầu. Cần kiểm tra cả hai trước khi kết luận lệnh có lỗi."], ['A package-manager token embedded in the command ID', "Nhúng mã xác thực của công cụ quản lý gói vào mã lệnh", "Mã lệnh dùng để nhận diện lần gửi lệnh, không phải nơi chứa bí mật của công cụ quản lý gói. Cách này không tạo điều kiện nhận lệnh và còn có thể làm lộ thông tin xác thực."],
    ], correct: ['C', 'D'], explanation: "Hãy kiểm tra SSM Agent, kết nối đến điểm cuối, quyền của nút và phạm vi được chọn. Đây là các điều kiện trực tiếp liên quan đến khả năng nhận lệnh, thay vì mở SSH hoặc bổ sung quyền quá rộng khi chưa rõ nguyên nhân.", tags: ['SSM-Agent', 'target-selection'] },
    { section: 'limits', en: 'A fleet run reaches MaxErrors. Several already-running targets later fail too. What is the correct interpretation?', vi: "Một lần thực thi trên nhóm máy chạm ngưỡng MaxErrors. Sau đó, một số tác vụ đang chạy cũng thất bại. Nên hiểu kết quả này như thế nào?", options: [
      ['MaxErrors must undo every previously completed target', "MaxErrors phải hoàn tác thao tác trên mọi đích đã hoàn thành", "MaxErrors là ngưỡng điều khiển việc tiếp tục giao công việc, không biến các thao tác thành một giao dịch có hoàn tác. Các thay đổi đã thực hiện không tự bị đảo ngược chỉ vì chạm ngưỡng."], ['The setting only measures CPU utilization', "Thiết lập này chỉ đo mức sử dụng CPU", "MaxErrors liên quan đến số lỗi khi thực thi công việc. Nó không phải chỉ số mức sử dụng CPU nên không thể diễn giải theo mức tải của máy."], ['Every in-flight task is atomically cancelled at the exact threshold', "Mọi tác vụ đang chạy đều bị hủy đồng thời ngay khi chạm ngưỡng", "Các tác vụ đã nhận việc vẫn có thể tiếp tục chạy và kết thúc theo cơ chế thực thi. Vì vậy, không thể coi ngưỡng là một thời điểm hủy nguyên tử mọi công việc đang chạy."], ['The threshold limits starting additional work; in-flight outcomes can increase final failures', "Ngưỡng hạn chế việc giao thêm công việc; kết quả của tác vụ đang chạy vẫn có thể làm tổng số lỗi tăng", "Khi ngừng giao thêm công việc, những tác vụ đã bắt đầu vẫn có thể phát sinh lỗi. Do đó, tổng lỗi cuối cùng có thể vượt ngưỡng mà không có nghĩa thiết lập đã mất tác dụng."],
    ], correct: ['D'], explanation: "MaxErrors hạn chế việc tiếp tục mở rộng công việc khi xuất hiện lỗi. Nó không hoàn tác phần đã xong và không bảo đảm mọi tác vụ đang chạy đều dừng trước khi phát sinh thêm lỗi.", tags: ['MaxErrors', 'in-flight'] },
    { section: 'limits', en: 'A remediation script is untested across Linux and Windows, but a tag selects both. What is the best rollout approach?', vi: "Tập lệnh khắc phục chưa được kiểm tra trên cả Linux và Windows, nhưng nhãn chọn đích bao gồm cả hai hệ điều hành. Nên triển khai theo cách nào?", options: [
      ['Validate platform-specific documents, canary a small scoped set, then expand with rate controls', "Xác minh tài liệu lệnh theo từng nền tảng, thử trên một nhóm nhỏ đã giới hạn rồi mở rộng có kiểm soát tốc độ", "Tài liệu đúng nền tảng xử lý khác biệt hệ điều hành; chạy thử trên nhóm nhỏ giúp kiểm chứng trước khi mở rộng. Giới hạn tốc độ còn hạn chế số máy chịu tác động nếu lỗi xuất hiện."], ['Run on every node at once so results are comparable', "Chạy đồng thời trên mọi nút để dễ so sánh kết quả", "Chạy rộng khi chưa kiểm chứng tương thích làm nhiều máy cùng chịu rủi ro. Khả năng so sánh kết quả không bù được việc bỏ qua bước xác minh trên phạm vi nhỏ."], ['Remove error logging to shorten command duration', "Bỏ nhật ký lỗi để rút ngắn thời gian chạy lệnh", "Bỏ nhật ký không giải quyết sự khác biệt giữa Linux và Windows. Nó còn làm mất thông tin cần để xác định máy nào lỗi và vì sao."], ['Set all node tags to production to simplify targeting', "Đặt nhãn của mọi nút thành production để dễ chọn đích", "Đồng nhất nhãn làm mất khả năng phân biệt môi trường và mở rộng phạm vi chọn máy. Cách này không kiểm chứng tính tương thích của tập lệnh với từng hệ điều hành."],
    ], correct: ['A'], explanation: "Khi tập lệnh còn phụ thuộc những giả định chưa được kiểm chứng về hệ điều hành, cần xác minh tài liệu lệnh và chạy thử trên nhóm nhỏ. Chỉ mở rộng sau khi có kết quả, với số đích chạy đồng thời và ngưỡng lỗi phù hợp.", tags: ['canary', 'platform'] },
    { section: 'limits', en: 'A Lambda repeatedly sets Auto Scaling desired capacity to 4 while target tracking tries to increase capacity under load. What is the primary design issue?', vi: "Lambda liên tục đặt desired capacity (số máy mong muốn) của Auto Scaling bằng 4, trong khi chính sách target tracking cố tăng số máy để đáp ứng tải. Vấn đề thiết kế chính là gì?", options: [
      ['The group has more than one metric available', "Nhóm có nhiều hơn một chỉ số để sử dụng", "Có nhiều chỉ số không tự gây ra xung đột. Vấn đề được mô tả là hai cơ chế cùng thay đổi số máy theo những mục tiêu không được phối hợp."], ['Competing controllers lack a clear authority and coordinated scaling policy', "Các bộ điều khiển cùng thay đổi cấu hình nhưng chưa có cơ chế quyết định rõ ràng và chính sách mở rộng được phối hợp", "Lambda áp lại mức cố định có thể đảo ngược việc tăng số máy của target tracking. Hai cơ chế cần được phối hợp để không liên tục ghi đè quyết định của nhau."], ['Every scaling event requires a CodeArtifact token', "Mọi sự kiện mở rộng tài nguyên đều cần mã xác thực CodeArtifact", "Mã xác thực CodeArtifact phục vụ truy cập kho gói, không điều phối desired capacity của Auto Scaling. Thiếu mã này không giải thích việc Lambda sửa ngược thay đổi theo tải."], ['The application must abandon metrics entirely', "Ứng dụng phải ngừng sử dụng mọi chỉ số", "Bỏ chỉ số làm mất thông tin phục vụ điều chỉnh theo tải nhưng không giải quyết hai cơ chế cùng sửa một cấu hình. Cần phối hợp quyền quyết định, không loại bỏ khả năng quan sát."],
    ], correct: ['B'], explanation: "Lambda đang buộc nhóm về một mức cố định trong khi target tracking điều chỉnh theo tải. Nhóm cần xác định cơ chế quyết định chính và phối hợp chính sách, giới hạn tối thiểu, tối đa cùng cách phản ứng với sự kiện để tránh sửa ngược nhau.", tags: ['Auto-Scaling', 'controller-conflict'] },
    { section: 'limits', en: 'Which TWO actions prevent an emergency runtime fix from being lost at the next deployment? Choose two.', vi: "Hai hành động nào giúp bản sửa khẩn cấp trên hệ thống đang chạy không bị mất trong lần triển khai tiếp theo? Chọn hai đáp án.", options: [
      ['Only document the fix in a private chat with no configuration change', "Chỉ ghi bản sửa trong cuộc trò chuyện riêng mà không cập nhật cấu hình", "Ghi chép giúp trao đổi thông tin nhưng không thay đổi cấu hình được dùng khi triển khai. Nếu nguồn cấu hình vẫn cũ, lần triển khai sau vẫn có thể ghi đè bản sửa."], ['Disable all future deployments permanently', "Ngừng vĩnh viễn mọi lần triển khai sau này", "Ngừng triển khai chỉ né tránh lần ghi đè tiếp theo và cản trở bảo trì. Cách này không đưa bản sửa vào nguồn cấu hình được quản lý để có thể triển khai an toàn."], ['Reflect the intended configuration in managed IaC or the authoritative source', "Cập nhật cấu hình mong muốn vào IaC hoặc nguồn cấu hình chuẩn được quản lý", "Khi nguồn cấu hình đã chứa bản sửa, lần tạo mới hoặc thay thế sau có cơ sở để tạo đúng trạng thái. Đây là bước cần thiết để không chỉ sửa tạm tài nguyên hiện tại."], ['Verify the next replacement or deployment preserves the corrected state', "Xác minh lần thay thế hoặc triển khai tiếp theo vẫn giữ trạng thái đã sửa", "Kiểm chứng lần triển khai tiếp theo cho biết nguồn cấu hình đã cập nhật có thực sự tạo ra trạng thái đúng hay không. Chỉ sửa tệp nguồn mà chưa xác minh vẫn chưa đủ bằng chứng."], ['Keep widening the emergency role after the incident', "Tiếp tục mở rộng quyền của role khẩn cấp sau sự cố", "Quyền rộng hơn không ngăn cấu hình cũ được áp lại trong lần triển khai sau. Nó còn để lại phạm vi truy cập lớn hơn nhu cầu mà không giải quyết nguyên nhân mất bản sửa."],
    ], correct: ['C', 'D'], explanation: "Sửa trực tiếp khôi phục trạng thái hiện tại, nhưng nguồn cấu hình cũ vẫn có thể ghi đè vào lần sau. Cần cập nhật IaC hoặc nguồn cấu hình chuẩn, rồi xác minh lần triển khai hay thay thế tiếp theo vẫn giữ được bản sửa.", tags: ['IaC', 'drift-prevention'] },
    { section: 'safety', en: 'The remediation API returned Success, but Config still displays the old evaluation briefly. What should happen next?', vi: "API khắc phục trả về Success, nhưng Config vẫn hiển thị kết quả đánh giá cũ trong một khoảng thời gian ngắn. Nên làm gì tiếp theo?", options: [
      ['Immediately reverse the resource to noncompliant', "Lập tức đưa tài nguyên về trạng thái không tuân thủ", "Kết quả hiển thị chưa cập nhật không chứng minh thao tác sửa đã làm sai cấu hình. Đưa tài nguyên về trạng thái cũ có thể phá bỏ một thay đổi đã thành công."], ['Grant administrator access and retry indefinitely', "Cấp quyền quản trị rồi thử lại vô hạn", "API đã trả về Success nên chưa có bằng chứng cho thấy thiếu quyền là nguyên nhân. Mở quyền và lặp lại thao tác có thể tạo tác động thừa mà không làm rõ trạng thái thực tế."], ['Delete the rule to force a green dashboard', "Xóa quy tắc để bảng giám sát chỉ còn trạng thái đạt yêu cầu", "Xóa quy tắc loại bỏ cơ chế đánh giá, không chứng minh tài nguyên đã đúng. Một bảng giám sát không còn cảnh báo không thay thế được bước xác minh sau khắc phục."], ['Read actual resource state, then observe or request appropriate reevaluation', "Đọc trạng thái thực tế của tài nguyên rồi theo dõi hoặc yêu cầu đánh giá lại theo cách phù hợp", "API, cấu hình hiện tại và kết quả đánh giá Config có thể cập nhật ở các thời điểm khác nhau. Đọc trạng thái trước giúp xác minh thao tác mà không sửa lại chỉ vì bản ghi đánh giá chưa đổi."],
    ], correct: ['D'], explanation: "Cần phân biệt kết quả gọi API, trạng thái thực tế của tài nguyên và kết quả đánh giá Config. Hãy xác minh cấu hình hiện tại, sau đó theo dõi hoặc yêu cầu đánh giá lại theo cơ chế phù hợp thay vì lập tức gửi thêm yêu cầu sửa.", tags: ['reevaluation', 'postcondition'] },
    { section: 'safety', en: 'A remediation repeatedly fails with AccessDenied. Which response is most appropriate?', vi: "Quy trình khắc phục liên tục thất bại với AccessDenied. Cách xử lý nào phù hợp nhất?", options: [
      ['Stop blind retries, inspect the denied API/identity/resource, and add only justified permissions', "Dừng gửi lại yêu cầu khi chưa rõ nguyên nhân; kiểm tra API, danh tính và tài nguyên bị từ chối, rồi chỉ bổ sung quyền có căn cứ", "AccessDenied cần được chẩn đoán theo chủ thể gọi, API và tài nguyên cụ thể. Lặp lại cùng yêu cầu không tự bổ sung quyền còn thiếu; chỉ nên cấp thêm những quyền đã được xác định là cần thiết."], ['Double retries every hour without checking identity', "Tăng gấp đôi số lần thử lại mỗi giờ mà không kiểm tra danh tính gọi API", "Tăng số lần gửi lại không thay đổi quyền của danh tính đang bị từ chối. Cách này chỉ tạo thêm chi phí và thông tin nhiễu khi nguyên nhân chưa được xử lý."], ['Disable audit logging so retries are less visible', "Tắt nhật ký kiểm toán để các lần thử lại ít xuất hiện hơn", "Tắt nhật ký làm mất thông tin cần để điều tra API và danh tính bị từ chối. Nó không thay đổi quyền nên quy trình vẫn có thể tiếp tục thất bại."], ['Apply the same runbook to every account to compare failures', "Áp dụng cùng runbook cho mọi tài khoản để so sánh lỗi", "Mở rộng sang nhiều tài khoản làm tăng phạm vi chịu tác động trong khi nguyên nhân ban đầu chưa rõ. Cần điều tra yêu cầu bị từ chối trước, không nhân rộng quy trình đang lỗi."],
    ], correct: ['A'], explanation: "Hãy phân loại lỗi trước khi quyết định thử lại. Với AccessDenied, cần tìm đúng danh tính, API và tài nguyên liên quan, rồi điều chỉnh quyền tối thiểu có cơ sở thay vì lặp lại yêu cầu hoặc mở rộng quyền tùy tiện.", tags: ['AccessDenied', 'bounded-retry'] },
    { section: 'automation', en: 'A runbook changes after approval but the trigger always uses an uncontrolled latest document version. What governance improvement best fits?', vi: "Runbook đã thay đổi sau khi được phê duyệt, nhưng nguồn kích hoạt luôn dùng phiên bản latest không được kiểm soát. Cần cải thiện quản trị theo cách nào?", options: [
      ['Only shorten the document name', "Chỉ rút ngắn tên tài liệu", "Độ dài tên không quyết định nội dung phiên bản được thực thi. Rút ngắn tên không bảo đảm lần chạy sử dụng đúng hành vi đã được phê duyệt."], ['Manage and approve document versions and allowed parameters used by execution', "Quản lý và phê duyệt phiên bản tài liệu cùng các tham số được phép dùng khi thực thi", "Phiên bản xác định nội dung chạy, còn tham số giới hạn phạm vi hành động. Quản lý cả hai giúp liên kết lần thực thi với nội dung đã kiểm chứng và được phép sử dụng."], ['Assume IAM alone proves the new script behavior is safe', "Cho rằng chỉ riêng IAM đã chứng minh hành vi của tập lệnh mới là an toàn", "IAM giới hạn quyền thao tác nhưng không chứng minh logic của phiên bản mới là đúng. Một tập lệnh vẫn có thể dùng API được phép sai mục đích hoặc nhắm sai tài nguyên trong phạm vi quyền."], ['Remove all step outputs to simplify the audit', "Bỏ mọi đầu ra của từng bước để đơn giản hóa kiểm toán", "Bỏ đầu ra làm giảm khả năng biết quy trình đã làm gì, không kiểm soát phiên bản được chạy. Cách này mất bằng chứng mà vẫn để nguồn kích hoạt dùng nội dung chưa được kiểm soát."],
    ], correct: ['B'], explanation: "IAM và quản lý phiên bản giải quyết hai yêu cầu khác nhau: giới hạn quyền và xác định nội dung thực thi. Cần kiểm soát phiên bản cùng tham số để lần chạy dùng đúng quy trình đã được phê duyệt trong phạm vi cho phép.", tags: ['document-version', 'change-control'] },
    { section: 'fleet', en: 'Run Command returns mixed results: some nodes succeeded, others were undeliverable. What is the best conclusion?', vi: "Run Command trả về kết quả hỗn hợp: một số nút thành công, trong khi một số nút không nhận được lệnh. Kết luận nào phù hợp nhất?", options: [
      ['Every node is now in the desired application state', "Mọi nút đều đã ở trạng thái ứng dụng mong muốn", "Các nút không nhận được lệnh chưa có bằng chứng đã thực hiện thao tác. Ngay cả kết quả thành công cũng cần được hiểu theo nội dung tài liệu đã kiểm tra, không thể suy ra toàn bộ nhóm đã đúng."], ['The successful nodes must be rolled back automatically by SSM', "SSM chắc chắn sẽ tự hoàn tác các thao tác trên những nút đã thành công", "Kết quả hỗn hợp không khiến thao tác trên nhiều nút trở thành một giao dịch có hoàn tác. Không thể giả định SSM sẽ tự đảo ngược những thay đổi đã hoàn thành."], ['Inspect per-node invocation and prerequisites before retrying the unresolved subset', "Kiểm tra kết quả từng nút và các điều kiện cần trước khi thử lại nhóm chưa xử lý được", "Kết quả từng lần gọi giúp tách các nút đã thành công khỏi nút chưa nhận lệnh. Kiểm tra Agent, kết nối, quyền và phạm vi cho nhóm còn lỗi giúp quyết định thử lại có căn cứ."], ['Retry every node with a destructive reset immediately', "Lập tức chạy lại trên mọi nút bằng thao tác đặt lại có tính phá hủy", "Chạy lại toàn bộ có thể tác động thừa lên các nút đã đúng và phá bỏ trạng thái đang hoạt động. Phương án này chưa điều tra vì sao một số nút không nhận được lệnh."],
    ], correct: ['C'], explanation: "Kết quả tổng hợp không thay thế trạng thái và đầu ra từng nút. Cần giữ thông tin của nhóm đã thành công, điều tra điều kiện nhận lệnh ở nhóm còn lỗi rồi mới quyết định thử lại phần chưa xử lý được.", tags: ['partial-failure', 'per-node-status'] },
    { section: 'safety', en: 'A resource has a legitimate temporary exception, but remediation and operators keep undoing each other. What should change?', vi: "Tài nguyên có một ngoại lệ tạm thời hợp lệ, nhưng quy trình khắc phục và người vận hành liên tục sửa ngược thay đổi của nhau. Cần điều chỉnh điều gì?", options: [
      ['Raise concurrency so the automation wins faster', "Tăng số đích chạy đồng thời để quy trình tự động thắng nhanh hơn", "Tăng mức đồng thời chỉ làm hành động tự động diễn ra nhanh hơn. Nó không giải quyết việc người vận hành và quy trình đang áp dụng hai chính sách khác nhau cho cùng tài nguyên."], ['Remove all resource ownership information', "Xóa mọi thông tin về người phụ trách tài nguyên", "Thông tin người phụ trách giúp xác nhận và giải quyết ngoại lệ. Xóa thông tin này làm khó việc phối hợp mà không tạo ra một trạng thái mong muốn thống nhất."], ['Keep both processes and rely on eventual luck', "Giữ nguyên hai quy trình và chờ may mắn", "Khi hai phía tiếp tục theo hai mục tiêu khác nhau, mỗi bên vẫn có thể sửa ngược bên còn lại. Không có cơ chế nào trong phương án này để quản lý ngoại lệ hoặc kết thúc xung đột."], ['Define a scoped, owned, expiring exception and align rule/action preconditions', "Xác định ngoại lệ có phạm vi, người phụ trách và thời điểm hết hạn; điều chỉnh điều kiện của quy tắc và hành động khắc phục cho phù hợp", "Ngoại lệ được quản lý cho biết tài nguyên nào được phép khác chính sách, ai chịu trách nhiệm và đến khi nào. Điều kiện đánh giá và hành động cần phản ánh điều đó để tránh sửa qua lại trong thời gian ngoại lệ còn hiệu lực."],
    ], correct: ['D'], explanation: "Người vận hành và quy trình tự động phải cùng hiểu trạng thái được phép của tài nguyên. Ngoại lệ cần có phạm vi, người phụ trách và thời hạn, đồng thời được phản ánh vào điều kiện đánh giá và khắc phục để tránh vòng lặp sửa ngược nhau.", tags: ['exception', 'policy-alignment'] },
  ], 5),
}
